304	+final class AgentUsageMonitor: ObservableObject {
305	+  @Published private(set) var snapshots: [AgentBackend: AgentQuotaSnapshot] = [:]
306	+  @Published private(set) var loading: Set<AgentBackend> = []
307	+
308	+  let codexSessionsURL: URL
309	+  let claudeCacheURL: URL
310	+  private let now: () -> Date
311	+  private var refreshTask: Task<Void, Never>?
312	+  private var watches: [DispatchSourceFileSystemObject] = []
313	+  private var watchedDescriptors: [Int32] = []
314	+  private var debounce: DispatchWorkItem?
315	+
316	+  init(
317	+    codexSessionsURL: URL = FileManager.default.homeDirectoryForCurrentUser
318	+      .appendingPathComponent(".codex/sessions", isDirectory: true),
319	+    claudeCacheURL: URL = ClaudeUsageBridge.defaultDirectory
320	+      .appendingPathComponent("claude-rate-limits.json"),
321	+    now: @escaping () -> Date = Date.init, startAutomatically: Bool = true
322	+  ) {
323	+    self.codexSessionsURL = codexSessionsURL
324	+    self.claudeCacheURL = claudeCacheURL
325	+    self.now = now
326	+    if let fixture = UITestFixture.usageSnapshot {
327	+      snapshots[fixture.backend] = fixture
328	+      return
329	+    }
330	+    if UITestFixture.usageAgentTitle != nil { return }
331	+    if startAutomatically {
332	+      refresh()
333	+      installWatches()
334	+    }
335	+  }
336	+
337	+  deinit {
338	+    refreshTask?.cancel()
339	+    debounce?.cancel()
340	+    for watch in watches { watch.cancel() }
341	+  }
342	+
343	+  func snapshot(for backend: AgentBackend) -> AgentQuotaSnapshot? {
344	+    snapshots[backend]?.fresh(at: now())
345	+  }
346	+
347	+  func refresh() {
348	+    // A seeded agent title is a model-only UI fixture. Never replace its deterministic snapshot
349	+    // (including the intentional unavailable case) by reading the developer's real provider files.
350	+    guard UITestFixture.usageAgentTitle == nil else {
351	+      loading.removeAll()
352	+      return
353	+    }
354	+    refreshTask?.cancel()
355	+    loading = Set(AgentBackend.allCases)
356	+    let codexURL = codexSessionsURL
357	+    let claudeURL = claudeCacheURL
358	+    let current = now()
359	+    refreshTask = Task.detached(priority: .utility) {
360	+      let codex = AgentUsageDecoding.readCodexSnapshot(sessionsRoot: codexURL, now: current)
361	+      let claude: AgentQuotaSnapshot? = {
362	+        guard let data = try? Data(contentsOf: claudeURL),
363	+          let attrs = try? FileManager.default.attributesOfItem(atPath: claudeURL.path),
364	+          let modified = attrs[.modificationDate] as? Date
365	+        else { return nil }
366	+        return AgentUsageDecoding.claude(data: data, capturedAt: modified, now: current)
367	+      }()
368	+      guard !Task.isCancelled else { return }
369	+      await MainActor.run {
370	+        self.snapshots = Dictionary(
371	+          uniqueKeysWithValues: [codex, claude].compactMap { $0 }.map { ($0.backend, $0) })
372	+        self.loading.removeAll()
373	+        self.rebuildWatches()
374	+      }
375	+    }
376	+  }
377	+
378	+  private func installWatches() { rebuildWatches() }
379	+
380	+  private func rebuildWatches() {
381	+    for watch in watches { watch.cancel() }
382	+    watches.removeAll()
383	+    watchedDescriptors.removeAll()
384	+    var paths = [codexSessionsURL, claudeCacheURL.deletingLastPathComponent()]
385	+    if let enumerator = FileManager.default.enumerator(
386	+      at: codexSessionsURL, includingPropertiesForKeys: [.isDirectoryKey],
387	+      options: [.skipsHiddenFiles, .skipsPackageDescendants])
388	+    {
389	+      for case let url as URL in enumerator {
390	+        if (try? url.resourceValues(forKeys: [.isDirectoryKey]).isDirectory) == true {
391	+          paths.append(url)
392	+        }
393	+      }
394	+    }
395	+    for url in paths where FileManager.default.fileExists(atPath: url.path) {
396	+      let descriptor = open(url.path, O_EVTONLY)
397	+      guard descriptor >= 0 else { continue }
398	+      let source = DispatchSource.makeFileSystemObjectSource(
399	+        fileDescriptor: descriptor, eventMask: [.write, .extend, .attrib, .rename, .delete],
400	+        queue: .main)
401	+      source.setEventHandler { [weak self] in self?.scheduleRefresh() }
402	+      source.setCancelHandler { close(descriptor) }
403	+      source.resume()
404	+      watches.append(source)
405	+      watchedDescriptors.append(descriptor)
406	+    }
407	+  }
408	+
409	+  private func scheduleRefresh() {
410	+    debounce?.cancel()
411	+    let item = DispatchWorkItem { [weak self] in self?.refresh() }
412	+    debounce = item
413	+    DispatchQueue.main.asyncAfter(deadline: .now() + 0.25, execute: item)
414	+  }
415	+}
