602	+      set -u
603	+      umask 077
604	+      bridge_dir=\(directory)
605	+      cache_file=\(cache)
606	+      metadata_file=\(metadata)
607	+      input_file="$bridge_dir/input.$$"
608	+      cache_tmp="$bridge_dir/rate-limits.$$"
609	+      cleanup() { /bin/rm -f "$input_file" "$cache_tmp"; }
610	+      trap cleanup EXIT HUP INT TERM
611	+      /bin/cat > "$input_file" || exit $?
612	+      if /usr/bin/plutil -extract rate_limits json -o "$cache_tmp" "$input_file" 2>/dev/null; then
613	+        /bin/chmod 600 "$cache_tmp" || exit $?
