649	+  }
650	+
651	+  private func writeJSON(_ object: Any, to url: URL, permissions: Int) throws {
652	+    guard JSONSerialization.isValidJSONObject(object) else { throw BridgeError.invalidSettings }
653	+    let data = try JSONSerialization.data(
654	+      withJSONObject: object, options: [.prettyPrinted, .sortedKeys])
655	+    try writer(data, url, permissions)
656	+  }
657	+
658	+  private func settingsPermissions() -> Int {
659	+    let attributes = try? fileManager.attributesOfItem(atPath: settingsURL.path)
660	+    return (attributes?[.posixPermissions] as? NSNumber)?.intValue ?? 0o600
661	+  }
662	+
663	+  private func equalJSON(_ lhs: Any, _ rhs: Any) -> Bool {
