1	import SwiftUI
2	
3	/// A status bar pinned to the bottom of a single pane (issue #49). Part of the pane itself, so every
4	/// pane in a split carries its own — it reflects THAT pane's tab: the open file's path (a file or
5	/// diff pane, issue #136) or the cwd (a terminal), the branch/bookmark, the run command's state
6	/// (only on the run tab), and the inline agent's diagnosis. Themed to match
7	/// the terminal (same background + foreground palette) so it reads as the pane's own chrome.
8	///
9	/// The diagnosis is a compact indicator that opens the full `TerminalAgentBanner` in a POPOVER — not
10	/// an overlay. A SwiftUI overlay's controls sit over the terminal's Metal `NSView`, which wins AppKit
11	/// hit-testing, so overlay buttons silently swallow clicks; a popover lives in its own window.
12	struct TerminalStatusBar: View {
13	  let target: TerminalTarget
14	  let tabID: TerminalTab.ID
15	  /// The pane's terminal, or nil for a non-terminal (diff / file / changeset) pane — which shows no
16	  /// cwd, run state or diagnosis, only the path (where there is one) and the branch.
17	  let state: TerminalState?
18	  /// The repo-relative path of the file this pane shows (issue #136), or nil for a pane that isn't
19	  /// a file: a terminal (which shows its cwd instead) or a changeset (whose in-pane `DiffViewer`
20	  /// header already carries the path). Supplied by `PaneLeafView` from `TabContent.filePath`.
21	  /// Defaulted, so the terminal mount doesn't have to say `filePath: nil`.
22	  var filePath: String? = nil
23	  @EnvironmentObject var store: AppStore
24	  @EnvironmentObject var agentManager: TerminalAgentManager
25	  @EnvironmentObject var agentUsage: AgentUsageMonitor
26	  @EnvironmentObject var claudeUsageBridge: ClaudeUsageBridge
27	  @State private var showingDiagnosis = false
28	  @State private var confirmingClaudeUsage = false
29	  @State private var claudeBridgeError: String?
30	  /// The AppKit view the cwd menu pops out of — see `MenuAnchor`.
31	  @State private var cwdMenuAnchor: NSView?
32	
33	  private let theme = ThemeService.shared
34	
35	  /// This pane's live cwd (observed state first, then the surface's last-known); nil for a diff pane.
36	  private var cwd: String? { state.flatMap { $0.cwd ?? $0.view.lastKnownCwd } }
37	
38	  private var isRunTab: Bool { state != nil && store.runTabID(for: target.id) == tabID }
39	
40	  private var diagnosis: AgentBannerState? { state == nil ? nil : agentManager.banners[tabID] }
41	
42	  private var activeAgent: AgentBackend? {
43	    state?.activeAgentBackend
44	  }
45	
46	  var body: some View {
47	    HStack(spacing: 12) {
48	      // Path and cwd are mutually exclusive in practice — a content pane has no cwd, a terminal has
49	      // no file — so they share the leading slot, ahead of the branch.
50	      pathSegment
51	      cwdSegment
52	      branchSegment
53	      // Diagnosis sits left-aligned right after the branch, not pushed to the far edge.
54	      if let diagnosis { diagnosisSegment(diagnosis) }
55	      Spacer(minLength: 8)
56	      DetachedSessionsButton(target: target)
57	      if isRunTab, let run = runStatePresentation { runSegment(run) }
58	      if let activeAgent { agentUsageSegment(activeAgent) }
59	    }
60	    // `.subheadline` (11pt) — the middle of the two sizes this bar has worn. `.caption` (10pt) was
61	    // too small to read at a glance for what the bar carries (a pane's identity: path, branch, run
62	    // state); `.callout` (12pt) read as content rather than chrome.
63	    .font(.subheadline)
64	    .foregroundStyle(theme.tokens.fgMuted)
65	    .lineLimit(1)
66	    .padding(.horizontal, 10)
67	    // Fixed, not vertical padding: the bar's height must not vary with its content (an icon, a
68	    // `ProgressView`) or a pane would resize as a diagnosis arrives. Held at 28pt across the font
69	    // change so panes don't reflow — the 11pt text just sits in a little more air.
70	    .frame(height: 28)
71	    .frame(maxWidth: .infinity)
72	    // `panel` (bg blended 5.5% toward fg), not the raw terminal `bg`: the bar reads as chrome rather
73	    // than as more terminal. Opaque and theme-derived, so it lifts by the same amount on a light or a
74	    // dark theme — a fixed white/black wash would invert on one of them.
75	    .background(theme.tokens.panel)
76	    .overlay(alignment: .top) { theme.tokens.border.frame(height: 1) }
77	    .accessibilityElement(children: .contain)
78	    .accessibilityIdentifier("terminal.statusBar")
79	    .task(id: activeAgent) {
80	      if activeAgent != nil { agentUsage.refresh() }
81	    }
82	    .alert("Enable Claude usage?", isPresented: $confirmingClaudeUsage) {
83	      Button("Cancel", role: .cancel) {}
84	      Button("Enable") {
